-- V107 스터디 노트(컴파일 스테이지만 --platform=$BUILDPLATFORM으로 네이티브화)에
-- 후속 개선 내용을 이어 붙인다: 이후 Playwright 설치로 런타임 스테이지가 무거워지며
-- 그 절충안의 한계를 겪었고, 결국 백엔드 CI를 frontend와 동일하게 GitHub Actions의
-- 네이티브 arm64 호스티드 러너(ubuntu-24.04-arm)로 전환해 QEMU 자체를 없앤 과정.
-- 이미 발행된 노트를 새 마이그레이션에서 UPDATE로 확장한다(원본 V107 파일은 수정하지 않음).
-- content_markdown 추가분은 V101~V107 컨벤션대로 16진 리터럴(X'...')로 이어붙인다.

UPDATE `study`
SET
  `summary` = 'GitHub Actions amd64 러너에서 ARM64 이미지를 빌드할 때 무거운 컴파일 스테이지만 --platform=$BUILDPLATFORM으로 네이티브 실행해 9~11분 걸리던 백엔드 빌드를 1분 36초로 단축했다가, 이후 런타임 스테이지가 Playwright 설치로 다시 무거워지며 이 절충안의 한계를 겪고 러너 자체를 네이티브 arm64로 전환한 과정까지 정리합니다.',
  `content_markdown` = CONCAT(`content_markdown`, X''),
  `updated_at` = NOW()
WHERE `slug` = 'docker-multiarch-build-platform-native-compile-stage';
